-- The M-Pesa callback token can be generated by the gateway and kept with
-- the paybill settings, so a host that offers only environment variables
-- (or an admin who would rather not handle it) does not have to set
-- TSP_MPESA_CALLBACK_TOKEN. When that variable is set it still wins.
--
-- The token is the secret part of the callback URLs Safaricom is given.
-- It is sealed with the master keyring like the Daraja credentials (same
-- key_version) and never returned by the API.

SET lock_timeout = '10s';

ALTER TABLE mpesa_settings
  ADD COLUMN callback_token_ciphertext bytea
    CHECK (callback_token_ciphertext IS NULL OR octet_length(callback_token_ciphertext) BETWEEN 29 AND 2048);

-- The guard now also treats a token change as a configuration change (the
-- api picks up the new token through the version, like the credentials).
CREATE OR REPLACE FUNCTION tsp_mpesa_settings_guard() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.id <> OLD.id THEN
    RAISE EXCEPTION 'mpesa settings: id is immutable' USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  IF NEW.environment IS DISTINCT FROM OLD.environment OR NEW.shortcode IS DISTINCT FROM OLD.shortcode
     OR NEW.stk_shortcode IS DISTINCT FROM OLD.stk_shortcode
     OR NEW.consumer_key_ciphertext IS DISTINCT FROM OLD.consumer_key_ciphertext
     OR NEW.consumer_secret_ciphertext IS DISTINCT FROM OLD.consumer_secret_ciphertext
     OR NEW.passkey_ciphertext IS DISTINCT FROM OLD.passkey_ciphertext
     OR NEW.callback_token_ciphertext IS DISTINCT FROM OLD.callback_token_ciphertext
     OR NEW.key_version IS DISTINCT FROM OLD.key_version
     OR NEW.callback_base_url IS DISTINCT FROM OLD.callback_base_url THEN
    NEW.version := OLD.version + 1;
    NEW.updated_at := now();
  ELSE
    NEW.version := OLD.version;
    NEW.updated_at := OLD.updated_at;
    NEW.updated_by := OLD.updated_by;
  END IF;
  RETURN NEW;
END $$;
